<?php
final class HutangKonveksiService {
    private PDO $pdo; private CollectionStore $store;
    public function __construct(PDO $pdo,CollectionStore $store){$this->pdo=$pdo;$this->store=$store;}
    private function id(string $p):string{return $p.'-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));}
    private function now():string{return date(DATE_ATOM);}
    public function createManual(array $p):array{
        $pegawai=trim((string)($p['id_pegawai']??''));$nom=round((float)($p['nominal']??0));if($pegawai==='')throw new RuntimeException('Pekerja/pegawai wajib dipilih.');if($nom<=0)throw new RuntimeException('Nominal hutang upah harus lebih dari Rp 0.');
        $list=$this->store->get('hutang_konveksi');$tgl=$p['tanggal']??date('Y-m-d');$r=['id_hutang'=>$this->id('HTK-MAN'),'tanggal'=>$tgl,'id_pegawai'=>$pegawai,'nama_pegawai'=>$p['nama_pegawai']??'Pegawai','divisi'=>strtolower((string)($p['divisi']??'jahit')),'id_spk'=>'MANUAL','nomor_spk'=>$p['nomor_referensi']??'MANUAL','total_upah'=>$nom,'kasbon_spk'=>0,'pembayaran_piutang'=>0,'hak_upah_bersih'=>$nom,'nominal_dicairkan_awal'=>0,'nominal_disimpan'=>$nom,'total_dibayar'=>0,'saldo_hutang'=>$nom,'status'=>'Aktif','idempotency_key'=>'HTK_MANUAL|'.$pegawai.'|'.$tgl.'|'.$nom.'|'.microtime(true),'catatan'=>'['.($p['kategori']??'Upah Manual').'] '.($p['catatan']??''),'created_at'=>$this->now(),'updated_at'=>$this->now(),'operator'=>$p['operator']??($_SESSION['username']??'system')];array_unshift($list,$r);$this->store->put('hutang_konveksi',$list);AuditService::log($this->pdo,'CREATE_HUTANG_KONVEKSI','HutangKonveksi',$r['id_hutang'],$r['nomor_spk'],null,$r);return ['status'=>'success','code'=>'HUTANG_KONVEKSI_MANUAL_CREATED','message'=>'Hutang Konveksi manual berhasil dicatat.','data'=>$r];
    }
    public function pay(array $p):array{
        $idp=trim((string)($p['id_pegawai']??''));$nom=round((float)($p['nominal_bayar']??0));$rek=trim((string)($p['id_rekening']??''));if($idp==='')throw new RuntimeException('Pegawai belum dipilih.');if($nom<=0)throw new RuntimeException('Nominal penarikan harus lebih dari 0.');if($rek==='')throw new RuntimeException('Rekening kas sumber wajib dipilih.');
        $hutang=$this->store->get('hutang_konveksi');$hist=$this->store->get('riwayat_bayar_hutang_konveksi');$keu=$this->store->get('keuangan');$idx=[];foreach($hutang as $i=>$h)if((string)($h['id_pegawai']??'')===$idp&&(float)($h['saldo_hutang']??0)>0)$idx[]=$i;usort($idx,fn($a,$b)=>strtotime((string)($hutang[$a]['tanggal']??$hutang[$a]['created_at']??'1970-01-01'))<=>strtotime((string)($hutang[$b]['tanggal']??$hutang[$b]['created_at']??'1970-01-01')));$total=0;foreach($idx as $i)$total+=(float)$hutang[$i]['saldo_hutang'];if($nom>$total)throw new RuntimeException('Nominal pembayaran melebihi saldo hutang pegawai.');$left=$nom;$generated=[];$tgl=$p['tanggal_bayar']??date('Y-m-d');foreach($idx as $i){if($left<=0)break;$before=(float)$hutang[$i]['saldo_hutang'];$pay=min($before,$left);$after=$before-$pay;$hutang[$i]['total_dibayar']=(float)($hutang[$i]['total_dibayar']??0)+$pay;$hutang[$i]['saldo_hutang']=$after;$hutang[$i]['status']=$after<=0?'Lunas':'Aktif';$hutang[$i]['updated_at']=$this->now();$row=['id_pembayaran'=>$this->id('BYR-HTK'),'tanggal'=>$tgl,'id_hutang'=>$hutang[$i]['id_hutang']??'','id_pegawai'=>$idp,'nama_pegawai'=>$hutang[$i]['nama_pegawai']??($p['nama_pegawai']??'Pegawai'),'nominal_bayar'=>$pay,'saldo_sebelum'=>$before,'saldo_sesudah'=>$after,'id_rekening'=>$rek,'rekening_kas'=>$p['rekening_kas']??'','metode_pembayaran'=>$p['metode_pembayaran']??'Tunai/Transfer','catatan'=>$p['catatan']??'','operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];$hist[]=$row;$generated[]=$row;$left-=$pay;}
        $journal=['id'=>$this->id('K'),'tanggal'=>$tgl,'tipe'=>'Keluar','nominal'=>$nom,'kategori'=>'Pembayaran Hutang Konveksi','modul'=>'Hutang Konveksi','id_rekening'=>$rek,'id_referensi'=>$generated[0]['id_pembayaran']??'','keterangan'=>'Pembayaran Hutang Konveksi '.($generated[0]['nama_pegawai']??''),'created_at'=>$this->now(),'created_by'=>$p['operator']??($_SESSION['username']??'system')];$keu[]=$journal;$this->store->putMany(['hutang_konveksi'=>$hutang,'riwayat_bayar_hutang_konveksi'=>$hist,'keuangan'=>$keu]);$remaining=max(0,$total-$nom);AuditService::log($this->pdo,'PAY_HUTANG_KONVEKSI','HutangKonveksi',null,$idp,null,['nominal'=>$nom,'sisa'=>$remaining]);return ['status'=>'success','code'=>'HUTANG_KONVEKSI_PAID','message'=>'Pembayaran Hutang Konveksi berhasil.','data'=>['riwayat'=>$generated,'sisa_saldo'=>$remaining,'jurnal'=>$journal]];
    }
}
